  function curZoneObj(){ for(var i=0;i<ZONES.length;i++){ var z=ZONES[i]; if(P.x>=z.x&&P.x<z.x+z.w&&P.y>=z.y&&P.y<z.y+z.h)return z; } return null; }
  function speedMul(){ var z=curZoneObj(); if(!z)return 1; if(z.weather==='rain')return 0.7; if(z.weather==='storm')return 0.85; if(z.weather==='dust')return 0.9; if(z.weather==='vacuum')return 1.12; return 1; }
  function itemTag(it){ if(it.verb){ if(WEAPON_VERBS[it.verb]) return 'arma '+ELEM[it.element].sym; return 'verbo '+(it.verb==='fly'?'VUELO':'ESCUDO'); } if(it.tool==='mine') return 'pico'; if(it.zoom) return 'x'+it.zoom; return 'herramienta'; }
