  function unequip(k){ P.equipped=P.equipped.filter(function(x){ return x!==k; }); if(ITEMS[k].verb==='fly'){ P.fly=false; } buildVerbs(); renderInv(); }
  function buildVerbs(){ var wrap=$('pv-verbs'); if(!wrap)return; wrap.innerHTML=''; P.equipped.forEach(function(k){ var it=ITEMS[k]; var b=document.createElement('button'); b.className='pv'; b.style.setProperty('--vc',ELEM[it.element]?ELEM[it.element].col:'#7fe3ff'); b.dataset.verb=it.verb; b.dataset.key=k; if(it.verb==='fly'){ b.innerHTML='🪽<span class="vl">VUELO</span><span class="vm"><i id="vm-fly"></i></span>'; b.onclick=function(){ if(P.flyCd>0)return; P.fly=!P.fly; toast(P.fly?'🪽 Vuelo activado':'🪽 Vuelo apagado'); }; } else if(it.verb==='shield'){ b.innerHTML='🛡️<span class="vl">'+P.shield+'</span><span class="vm"><i id="vm-sh" style="width:'+(P.shield/3*100)+'%"></i></span>'; b.onclick=function(){ if(P.shield<=0||P.shieldT>0)return; P.shieldT=3000; P.shield--; buildVerbs(); toast('🛡️ Escudo activo (3s)'); }; } wrap.appendChild(b); }); }
  function showTip(anchor,it){ var tip=$('pv-tip'); if(!tip)return; var hr=host.getBoundingClientRect(); var r=anchor.getBoundingClientRect(); var extra=''; if(it.verb&&WEAPON_VERBS[it.verb])extra='<span class="ed">🗡️ Arma con '+ELEM[it.element].sym+'.</span>'; else if(it.verb==='fly')extra='<span class="ed">🪽 Verbo VUELO con aguante.</span>'; else if(it.verb==='shield')extra='<span class="ed">🛡️ Verbo ESCUDO 3 cargas.</span>'; else if(it.tool==='mine')extra='<span class="ed">⛏️ Pico: acelera extraccion.</span>'; else if(it.zoom)extra='<span class="ed">🔭 Pulsa T (x'+it.zoom+').</span>'; tip.innerHTML='<b>'+it.emoji+' '+it.name+'</b> · '+it.blurb+extra+'<span class="ed">📘 '+it.edu+'</span>'; tip.classList.add('show'); var l=r.left-hr.left,t=r.top-hr.top-tip.offsetHeight-8; if(t<4)t=r.bottom-hr.top+8; if(l+240>hr.width)l=hr.width-244; if(l<4)l=4; tip.style.left=l+'px'; tip.style.top=t+'px'; clearTimeout(tip._t); tip._t=setTimeout(function(){ tip.classList.remove('show'); },3400); }
  function telescopeZoom(){ var eq=P.equipped.filter(function(k){ return k.indexOf('tel_')===0; }); return eq.length?Math.max.apply(null,eq.map(function(k){ return ITEMS[k].zoom; })):0; }
  function toggleSky(){ var hasTel=P.equipped.some(function(k){ return k.indexOf('tel_')===0; }); if(!hasTel){ toast('🔭 Equipa un telescopio y pulsa T.'); return; } skyOpen=!skyOpen; var sky=$('pv-sky'); if(sky)sky.classList.toggle('open',skyOpen); if(skyOpen)drawSky(); }
