  function renderForge(){ var fl=$('pv-forgelist'); if(!fl)return; var fr=$('pv-frag'); if(fr)fr.textContent=P.frags; var FORGE={fuerza:{name:'Fuerza Forjada',emoji:'💪',cost:3,desc:'+50% dano a jefes'},alas:{name:'Alas Forjadas',emoji:'🪽',cost:3,desc:'+aguante de vuelo'},ojo:{name:'Ojo del Director',emoji:'👁️',cost:5,desc:'Revela el minimapa'}}; fl.innerHTML=Object.keys(FORGE).map(function(k){ var f=FORGE[k]; var done=P.skills[k]>0; return '<div class="prw"><div style="flex:1"><div class="l">'+f.emoji+' '+f.name+(done?' ✅':'')+'</div><div class="ed">'+f.desc+'</div></div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">'+f.cost+' 🔷</span>'+(done?'<span class="co" style="color:#39ff88">forjado</span>':'<button class="pbtn" data-forge="'+k+'">Forjar</button>')+'</span></div>'; }).join(''); fl.querySelectorAll('[data-forge]').forEach(function(btn){ btn.addEventListener('click',function(){ var k=btn.getAttribute('data-forge'); var f=FORGE[k]; if(P.skills[k]>0){ toast('Ya forjado'); return; } if(P.frags>=f.cost){ P.frags-=f.cost; P.skills[k]=1; applySkills(); renderForge(); renderInv(); saveSave(); toast('⚒️ Forjado: '+f.name); logChron('Forjaste '+f.name); } else { toast('Necesitas '+f.cost+' 🔷'); } }); }); }
  function openParcel(p){ curParcel=p; renderParcel(); var el=$('pv-parcel'); if(el)el.style.display='flex'; }
