  function parcelEmoji(p){ if(!p.owner)return '🏞️'; if(p.care<=0.15)return '🏚️'; if(p.rent)return '🧑‍🌾'; return '🏠'; }
  function renderParcel(){ if(!curParcel)return; var p=curParcel; var t=$('pv-parcel-title'); if(t)t.textContent=parcelEmoji(p)+' Parcela en '+p.zone; var sub=$('pv-parcel-sub'); if(sub)sub.textContent=p.owner?('Nivel '+p.level+' · Cuidado '+Math.round(p.care*100)+'% · Renta '+p.accrued.toFixed(1)+' 💠'):'Parcela libre. Comprala para generar ingresos.'; var body=$('pv-parcel-body'); if(!body)return; var zfl=flora[p.zone]||0.5; var html=''; if(!p.owner){ html+='<div class="prw"><div class="l">🏞️ Parcela virgen</div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">'+parcelCost(p)+' 💠</span><button class="pbtn" data-pact="buy">Comprar</button></span></div><div class="ed" style="padding:6px">Renta/seg. 8% al Fondo ciudad, 2% Tesoro ICME. Si no produces, no pagas nada.</div>'; } else { html+='<div class="prw"><div class="l">💼 Trabajar</div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">+rinde</span><button class="pbtn" data-pact="work">Trabajar</button></span></div>'; html+='<div class="prw"><div class="l">⬆️ Mejorar (Nv '+p.level+'→'+(p.level+1)+')</div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">'+(60*p.level)+' 💠</span><button class="pbtn" data-pact="upgrade">Mejorar</button></span></div>'; html+='<div class="prw"><div class="l">'+(p.rent?'🧑‍🌾 Arrendada':'📜 Arrendar')+'</div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">'+(p.rent?'pasiva':'')+'</span><button class="pbtn" data-pact="rent">'+(p.rent?'Quitar':'Arrendar')+'</button></span></div>'; html+='<div class="prw"><div class="l">💰 Cobrar renta</div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">'+p.accrued.toFixed(1)+' 💠</span><button class="pbtn" data-pact="collect">Cobrar</button></span></div>'; var h=HOOK(); if(h&&h.parcelHTML){ html+=h.parcelHTML(p); } html+='<div class="ed" style="padding:6px">Flora '+Math.round(zfl*100)+'% · Nv ciudad. Los muebles dan PLUS real.</div>'; } body.innerHTML=html; body.querySelectorAll('[data-pact]').forEach(function(btn){ btn.addEventListener('click',function(){ parcelAction(btn.getAttribute('data-pact')); }); }); body.querySelectorAll('[data-furn]').forEach(function(btn){ btn.addEventListener('click',function(){ var h2=HOOK(); if(h2&&h2.furn){ h2.furn(p, btn.getAttribute('data-furn')); renderParcel(); } }); }); }
  function parcelAction(act){ var p=curParcel; if(!p)return; if(act==='buy'){ var c=parcelCost(p); if(P.pp>=c){ P.pp-=c; p.owner='you'; p.care=1; p.furn=p.furn||[]; flora[p.zone]=Math.min(1,(flora[p.zone]||0.5)+0.1); renderParcel(); renderInv(); saveSave(); toast('🏠 Parcela comprada en '+p.zone); logChron('Compraste parcela en '+p.zone); } else toast('💠 PP insuficientes'); } else if(act==='work'){ p.care=Math.min(1,p.care+0.25); flora[p.zone]=Math.min(1,(flora[p.zone]||0.5)+0.03); var gain=Math.round((2+p.level)*director.mult); P.pp+=gain; toast('💼 +'+gain+' 💠 y la zona florece'); renderParcel(); renderInv(); saveSave(); } else if(act==='upgrade'){ var cost=60*p.level; if(P.pp>=cost){ P.pp-=cost; p.level++; toast('⬆️ Nivel '+p.level); logChron('Mejoraste parcela a nivel '+p.level); renderParcel(); renderInv(); saveSave(); } else toast('💠 PP insuficientes'); } else if(act==='rent'){ p.rent=!p.rent; toast(p.rent?'📜 Arrendada (pasiva)':'Renta quitada'); logChron(p.rent?'Arrendaste parcela':'Quitaste renta'); renderParcel(); saveSave(); } else if(act==='collect'){ if(p.accrued>=1){ var g=Math.floor(p.accrued); P.pp+=g; p.accrued-=g; toast('💰 +'+g+' 💠'); renderParcel(); renderInv(); saveSave(); } else toast('Sin renta acumulada'); } }
  function tickParcels(){ PARCELS.forEach(function(p){ if(p.owner!=='you')return; var zfl=flora[p.zone]||0.5; if(p.care<=0.05){ return; } var fb={rent:0,care:0,city:0,flora:0}; var h=HOOK(); if(h&&h.furnBonus) fb=h.furnBonus(p); var base=(0.6+p.level*0.5); var prod=base*p.care*(0.5+0.5*zfl)*(p.rent?0.8:1.0)*director.mult*(1+fb.rent); var taxC=prod*0.08; var taxK=prod*0.02; p.accrued+=(prod-taxC-taxK); p.care=Math.max(0,p.care-(p.rent?0.01:0.02)*(1-Math.min(0.8,fb.care))); if(p.care<=0.05){ flora[p.zone]=Math.max(0,(flora[p.zone]||0.5)-0.02); } if(fb.flora>0) flora[p.zone]=Math.min(1,(flora[p.zone]||0.5)+fb.flora*0.01); }); }
  function drawSky(){ var sky=$('pv-sky'); var sc=host.querySelector('#pv-skycanvas'); if(!sc)return; var w=sc.clientWidth||W,h=sc.clientHeight||H; if(sc.width!==w)sc.width=w; if(sc.height!==h)sc.height=h; var c=sc.getContext('2d'); var z=curZoneObj(); var zoom=telescopeZoom()||2; var sz=$('pv-skyzoom'); if(sz)sz.textContent='x'+zoom; c.clearRect(0,0,w,h); var g=c.createRadialGradient(w/2,h/2,0,w/2,h/2,Math.max(w,h)); g.addColorStop(0,'#0a1030'); g.addColorStop(1,'#02030a'); c.fillStyle=g; c.fillRect(0,0,w,h); for(var i=0;i<140;i++){ var x=(Math.sin(i*12.9898)*43758.5453)%1; var y=(Math.sin(i*78.233)*12543.123)%1; var px=(Math.abs(x))*w,py=(Math.abs(y))*h; var tw=0.4+0.6*Math.abs(Math.sin(performance.now()/600+i)); c.globalAlpha=tw; c.fillStyle='#fff'; c.beginPath(); c.arc(px,py,(i%9===0?1.8:0.9),0,7); c.fill(); } c.globalAlpha=1; drawBody(c,w,h,z?z.body:'none'); var set=SKY_BY_SET[z?z.skySet:'north']||['orion']; var cx=w/2,cy=h/2; set.forEach(function(key,si){ var con=CONSTS[key]; if(!con)return; var offx=(si-(set.length-1)/2)*0.18; con.stars.forEach(function(s){ var sx=cx+(s[0]-0.5+offx)*w*zoom,sy=cy+(s[1]-0.5)*h*zoom; if(sx<-20||sx>w+20||sy<-20||sy>h+20)return; c.fillStyle=key==='sirius'?'#bfe3ff':'#fff'; c.shadowColor='#7fe3ff'; c.shadowBlur=key==='sirius'?14:6; c.beginPath(); c.arc(sx,sy,key==='sirius'?4:2.4,0,7); c.fill(); c.shadowBlur=0; }); c.strokeStyle='rgba(127,227,255,.5)'; c.lineWidth=1; con.lines.forEach(function(pair){ var A=con.stars[pair[0]],B=con.stars[pair[1]]; var ax=cx+(A[0]-0.5+offx)*w*zoom,ay=cy+(A[1]-0.5)*h*zoom,bx=cx+(B[0]-0.5+offx)*w*zoom,by=cy+(B[1]-0.5)*h*zoom; c.beginPath(); c.moveTo(ax,ay); c.lineTo(bx,by); c.stroke(); }); var lx=cx+offx*w*zoom,ly=cy-0.32*h*zoom; if(lx>0&&lx<w&&ly>0&&ly<h){ c.fillStyle='#9fe3ff'; c.font='12px Cinzel, serif'; c.textAlign='center'; c.fillText(con.name,lx,ly); c.textAlign='left'; } }); var fact=(CONSTS[set[0]]?CONSTS[set[0]].fact:''); var card=$('pv-skycard'); if(card)card.innerHTML='<b>'+z.name+' · cielo '+(z.skySet)+'</b><br>'+fact; }
  function drawBody(c,w,h,body){ if(body==='earth'){ c.save(); c.shadowColor='#3da5ff'; c.shadowBlur=30; var g=c.createRadialGradient(w*0.82,h*0.22,2,w*0.82,h*0.22,26); g.addColorStop(0,'#bfe3ff'); g.addColorStop(.5,'#2b6bff'); g.addColorStop(1,'#0a2a5a'); c.fillStyle=g; c.beginPath(); c.arc(w*0.82,h*0.22,24,0,7); c.fill(); c.shadowBlur=0; c.fillStyle='rgba(57,255,136,.7)'; c.beginPath(); c.arc(w*0.8,h*0.2,6,0,7); c.arc(w*0.85,h*0.27,4,0,7); c.fill(); c.restore(); } else if(body==='moon'){ c.save(); c.shadowColor='#cfd8ff'; c.shadowBlur=18; c.fillStyle='#dfe3ee'; c.beginPath(); c.arc(w*0.8,h*0.2,16,0,7); c.fill(); c.fillStyle='rgba(0,0,0,.15)'; c.beginPath(); c.arc(w*0.78,h*0.18,3,0,7); c.arc(w*0.83,h*0.23,2,0,7); c.fill(); c.restore(); } else if(body==='gasgiant'){ c.save(); c.shadowColor='#ff7a3d'; c.shadowBlur=24; var g=c.createLinearGradient(w*0.7,h*0.1,w*0.9,h*0.3); g.addColorStop(0,'#ff7a3d'); g.addColorStop(.5,'#ffd479'); g.addColorStop(1,'#a9772f'); c.fillStyle=g; c.beginPath(); c.arc(w*0.8,h*0.2,22,0,7); c.fill(); c.strokeStyle='rgba(255,255,255,.25)'; c.lineWidth=2; c.beginPath(); c.ellipse(w*0.8,h*0.2,34,8,0.3,0,7); c.stroke(); c.restore(); } }
  function openShop(){ renderShop(); var s=$('pv-shop'); if(s)s.style.display='flex'; }
  function closeShop(){ var s=$('pv-shop'); if(s)s.style.display='none'; }
  function renderShop(){ var buyKeys=['tel_bronce','tel_espejo','tel_interf','escoba','micro','pico_cristal','pot','guante_rayo','hoja_forja','daga_marea','pluma_cefiro','alas_ether','aegis']; var z=curZoneObj(); var bl=$('pv-buylist'); if(bl)bl.innerHTML=buyKeys.map(function(k){ var it=ITEMS[k]; var baseP=it.val; var price=baseP; var dtag=''; var locked=''; var h=HOOK(); if(h){ if(h.buyPrice) price=h.buyPrice(k,baseP); var di=h.demandOf?h.demandOf(k):0; if(di>0){ dtag=' <span class="demand">🔥 +'+Math.round((price/baseP-1)*100)+'%</span>'; } if(h.canBuy){ var ck=h.canBuy(k); if(!ck.ok){ locked=' locked'; } } } var tag=itemTag(it); return '<div class="prw" data-tipkey="'+k+'"><div style="flex:1"><div class="l">'+it.emoji+' '+it.name+' <span style="opacity:.7">· '+tag+'</span>'+dtag+'</div><div class="ed">📘 '+it.edu+'</div></div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">'+price+' 💠</span><button class="pbtn'+locked+'" data-buy="'+k+'" data-price="'+price+'"'+(locked?' disabled':'')+'>Comprar</button></span></div>'; }).join(''); var sell=P.inv.filter(function(k){ return ITEMS[k]; }); var sl=$('pv-selllist'); if(sl)sl.innerHTML=sell.length?sell.map(function(k){ return '<div class="prw"><div class="l">'+ITEMS[k].emoji+' '+ITEMS[k].name+'</div><span style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><span class="co">+'+Math.floor(ITEMS[k].val/2)+' 💠</span><button class="pbtn gh" data-sell="'+k+'">Vender</button></span></div>'; }).join(''):'<div style="font-size:12px;color:#8090b0;padding:6px">Nada que vender.</div>';
    host.querySelectorAll('#pv-buylist [data-tipkey]').forEach(function(row){ row.addEventListener('mouseenter',function(){ showTip(row,ITEMS[row.dataset.tipkey]); }); });
    host.querySelectorAll('#pv-buylist [data-buy]').forEach(function(btn){ btn.addEventListener('click',function(){ if(btn.classList.contains('locked')){ var h=HOOK(); if(h&&h.canBuy){ var m=h.canBuy(btn.getAttribute('data-buy')); toast(m.msg); } return; } buy(btn.getAttribute('data-buy'),+btn.getAttribute('data-price')); }); });
    host.querySelectorAll('#pv-selllist [data-sell]').forEach(function(btn){ btn.addEventListener('click',function(){ sell(btn.getAttribute('data-sell')); }); });
  }
  function buy(k,price){ var h=HOOK(); if(h&&h.canBuy){ var ck=h.canBuy(k); if(!ck.ok){ toast(ck.msg); return; } } var cost=price||ITEMS[k].val; if(P.pp>=cost){ P.pp-=cost; addItem(k); if(h&&h.onBuy) h.onBuy(k); renderShop(); toast('Compraste '+ITEMS[k].name); } else toast('💠 PP insuficientes'); }
  function sell(k){ var v=Math.floor(ITEMS[k].val/2); removeItem(k); P.pp+=v; renderInv(); renderShop(); toast('Vendiste '+ITEMS[k].name+' +'+v+' PP'); }
  var mg={on:false,pos:0,dir:1,round:0,hits:0,zoneStart:0,zoneW:0};
  function openMG(){ mg={on:true,pos:0,dir:1,round:1,hits:0,zoneStart:0,zoneW:0}; newMGRound(); var m=$('pv-mg'); if(m)m.style.display='flex'; }
  function newMGRound(){ mg.zoneW=18+Math.random()*10; mg.zoneStart=15+Math.random()*(70-mg.zoneW); mg.pos=0; mg.dir=1; var z=$('pv-mgzone'); if(z){ z.style.left=mg.zoneStart+'%'; z.style.width=mg.zoneW+'%'; } var info=$('pv-mginfo'); if(info)info.textContent='Ronda '+mg.round+' / 3 - Aciertos: '+mg.hits; }
  function mgHit(){ if(!mg.on)return; var inZ=mg.pos>=mg.zoneStart&&mg.pos<=mg.zoneStart+mg.zoneW; if(inZ){ mg.hits++; toast('🎯 +20 PP'); P.pp+=20; renderInv(); } else toast('❌ Fallaste'); if(mg.round>=3){ setTimeout(function(){ toast('🕹️ '+mg.hits+'/3 +'+(mg.hits*5)+' PP'); P.pp+=mg.hits*5; renderInv(); closeMG(); },400); } else { mg.round++; setTimeout(newMGRound,400); } }
  function closeMG(){ mg.on=false; var m=$('pv-mg'); if(m)m.style.display='none'; }
  function jump(){ if(P.jumpT>0||P.fly)return; var z=curZoneObj(); var g=z?z.grav:1; P.jumpT=600*(1/g); P.jumpH=26*(1/g); }
  function tryMine(){ var z=curZoneObj(); var node=null; for(var i=0;i<resources.length;i++){ var n=resources[i]; if(n.amt>0&&n.cd<=0&&dist(P,n)<46){ node=n; break; } } if(!node)return false; var def=RES_DEF[node.type]; var toolMul=P.pickaxe?(ITEMS[P.pickaxe].speed||1):1; var wxMul=(z&&z.weather==='rain')?0.8:1; var dur=def.t/(toolMul*wxMul); P.mining={node:node,t0:performance.now(),dur:dur}; var mb=$('pv-minebar'); if(mb)mb.style.display='block'; toast('⛏️ Extrayendo '+node.type+'...'); return true; }
  function playerAttack(){ if(P.atkCd>0)return; P.atkCd=12; var we=weaponElement(); var tx=boss?boss.x:(P.x+P.dir.x*120); var ty=boss?boss.y:(P.y+P.dir.y*120); var dx=tx-P.x,dy=ty-P.y,d=Math.hypot(dx,dy)||1; pBullets.push({x:P.x,y:P.y,vx:dx/d*7,vy:dy/d*7,life:80,elem:we,col:we?ELEM[we].col:'#cfe8ff'}); }
  function startBoss(id){ var d=BOSS_DEFS[id]; if(boss&&boss.def===d){ toast('Ya estas en combate.'); return; } boss={def:d,x:d.px,y:d.py,hp:d.hp,maxhp:d.hp,cd:50,pi:0,t:0,laser:null,stun:0,blind:0,freeze:0,burn:0,lastElem:null,lastT:0,phase:0}; var nm=$('pv-bossname'); if(nm)nm.textContent=d.emoji+' '+d.name; var er=$('pv-bossera'); if(er)er.textContent=d.era; if(nm)nm.style.color=ELEM[d.element]?ELEM[d.element].col:'#e8b15c'; var bf=$('pv-bossfill'); if(bf)bf.style.background='linear-gradient(90deg,'+(ELEM[d.element]?ELEM[d.element].col:'#e8b15c')+',#fff6)'; var bb=$('pv-bossbar'); if(bb)bb.style.display='block'; toast('⚔️ '+d.name+' - '+d.tip,3000); }
